item.description:
.kd{font-family:Poppins,-apple-system,Segoe UI,Arial,sans-serif;color:#2b2b2b;font-size:17px;line-height:1.65;max-width:1080px;margin:0 auto;}
.kd h2{font-family:Montserrat,Georgia,serif;font-weight:800;font-size:28px;color:#1f2a17;text-align:center;margin:44px 0 8px;line-height:1.25;}
.kd h3{font-family:Montserrat,Georgia,serif;font-weight:800;font-size:22px;color:#1f2a17;margin:26px 0 8px;}
.kd .sub{text-align:center;color:#777;margin:0 0 20px;font-size:16px;}
.kd img,.kd video{max-width:100%;border-radius:14px;display:block;}
.kd p{margin:0 0 14px;}
.kd-band{background:#eef1e6;border-radius:18px;padding:28px 24px;margin:28px 0;}
.kd-check{list-style:none;padding:0;margin:14px auto;max-width:660px;}
.kd-check li{padding:9px 0 9px 34px;position:relative;font-size:18px;}
.kd-check li:before{content:"\2714";position:absolute;left:0;color:#527B29;font-weight:800;}
.kd-trust{display:flex;flex-wrap:wrap;gap:12px;justify-content:center;margin:18px 0;}
.kd-trust span{background:#fff;border:1px solid #dfe6d3;border-radius:30px;padding:9px 16px;font-size:14px;font-weight:600;color:#3f5d2f;}
.kd-icons{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0;text-align:center;}
.kd-icons .e{font-size:30px}
.kd-icons .t{font-size:13px;font-weight:700;color:#4a5d3a;margin-top:4px}
.kd-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:18px 0;}
.kd-grid .c{background:#fafaf5;border:1px solid #eee;border-radius:14px;padding:20px 12px;text-align:center;}
.kd-grid .e{font-size:36px;line-height:1;}
.kd-grid .t{font-weight:700;margin-top:8px;font-size:15px;}
.kd-mech{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:20px 0;}
.kd-mech .c{text-align:center;}
.kd-mech .ring{width:78px;height:78px;border-radius:50%;background:#e7efdc;display:flex;align-items:center;justify-content:center;font-size:34px;margin:0 auto 8px;}
.kd-mech .t{font-weight:700;font-size:14px;color:#3f5d2f;}
.kd-ing{display:flex;gap:18px;align-items:flex-start;border-bottom:1px solid #eee;padding:20px 0;}
.kd-ing .ring{flex:0 0 76px;width:76px;height:76px;border-radius:50%;background:#f0f4ea;border:1px solid #e2e9d6;display:flex;align-items:center;justify-content:center;font-size:34px;}
.kd-ing b{font-size:19px;color:#1f2a17;}
.kd-ing sup{color:#8aa06a;font-size:12px}
.kd-step{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:center;margin:20px 0;}
.kd-step .n{display:inline-block;background:#527B29;color:#fff;border-radius:50%;width:36px;height:36px;line-height:36px;text-align:center;font-weight:800;margin-bottom:6px;}
.kd-quote{background:#f7faf3;border-left:5px solid #8aa06a;border-radius:10px;padding:18px 20px;margin:20px 0;font-size:17px;}
.kd-quote .who{color:#666;font-size:15px;margin-top:8px;}
.kd-rev{display:flex;gap:15px;background:#fafafa;border:1px solid #eee;border-radius:14px;padding:17px;margin:12px 0;}
.kd-rev img{width:76px;height:76px;border-radius:50%;object-fit:cover;flex:0 0 76px;}
.kd-rev .stars{color:#f5a623;letter-spacing:1px;}
.kd-rev .vb{color:#2e7d32;font-weight:700;font-size:12px;}
.kd-rev .nm{font-weight:700;}
.kd-rev .rt{font-weight:700;color:#1f2a17;margin:4px 0 2px;}
.kd-rev p{margin:3px 0 0;font-size:15px;}
.kd-wall{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0;}
.kd-wall .c{border:1px solid #eee;border-radius:14px;overflow:hidden;background:#fff;}
.kd-wall .c img,.kd-wall .c video{width:100%;height:210px;object-fit:cover;border-radius:0;}
.kd-wall .b{padding:12px 13px;}
.kd-wall .b .nm{font-weight:700;font-size:15px}
.kd-wall .b .stars{color:#f5a623;font-size:14px}
.kd-wall .b p{font-size:14px;margin:5px 0 0;color:#555}
.kd-cta{display:block;text-align:center;background:#527B29;color:#fff!important;font-family:Montserrat;font-weight:800;font-size:21px;padding:20px;border-radius:999px;text-decoration:none;margin:26px auto;max-width:540px;box-shadow:0 8px 20px rgba(82,123,41,.3);}
.kd-rated{text-align:center;color:#666;font-size:15px;margin:-14px 0 22px;}
.kd-guar{background:#f3f6ee;border:2px solid #cfe0bd;border-radius:16px;padding:26px;text-align:center;margin:28px 0;}
.kd-faq{border-bottom:1px solid #e6e6e6;padding:15px 0;}
.kd-faq b{font-size:17px;}
.kd-pay{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;font-size:13px;color:#888;margin:10px 0 0}
.kd-pay span{background:#f4f4f4;border-radius:6px;padding:6px 11px;font-weight:600}
.kd-ref{font-size:13px;color:#8d8d8d;line-height:1.9;}
.kd-ref a{color:#8d8d8d;word-break:break-all;}
.kd-disc{font-size:11px;color:#b9b9b9;border-top:1px solid #f0f0f0;padding-top:12px;margin-top:26px;line-height:1.5;}
@media(max-width:760px){.kd-grid,.kd-mech,.kd-wall{grid-template-columns:repeat(2,1fr)}.kd-step{grid-template-columns:1fr}.kd-icons{grid-template-columns:repeat(2,1fr)}.kd h2{font-size:23px}}





